using System;using System.Diagnostics;using System.IO;using System.Reflection;using System.Windows.Forms;
class NativeObsInstaller {
 [STAThread]static void Main(){Application.EnableVisualStyles();var form=new Form{Text="Freecam · OBS 33.0.1 · эксперимент",Width=570,Height=250,StartPosition=FormStartPosition.CenterScreen};var label=new Label{Left=24,Top=20,Width=510,Height=100,Text="Установка нативного модуля Freecam.\nЗакройте OBS. Выберите файл obs64.exe вашей установки.\nПоддерживается только OBS 33.0.1. Эфир не запускается.\nСначала проверьте работу на локальной записи."};form.Controls.Add(label);var button=new Button{Left=24,Top=130,Width=500,Height=42,Text="Выбрать OBS и установить модуль"};form.Controls.Add(button);button.Click+=(s,e)=>{try{if(Process.GetProcessesByName("obs64").Length>0)throw new Exception("Закройте OBS перед установкой модуля.");using(var dialog=new OpenFileDialog{Filter="OBS Studio|obs64.exe",Title="Выберите obs64.exe"}){if(dialog.ShowDialog()!=DialogResult.OK)return;var bin=Path.GetDirectoryName(dialog.FileName);if(FileVersionInfo.GetVersionInfo(Path.Combine(bin,"obs.dll")).ProductVersion!="33.0.1")throw new Exception("Эта экспериментальная сборка рассчитана только на OBS 33.0.1.");var root=Path.GetFullPath(Path.Combine(bin,"..",".."));var target=Path.Combine(root,"obs-plugins","64bit","freecam-obs.dll");Directory.CreateDirectory(Path.GetDirectoryName(target));var temporary=target+".new-"+Guid.NewGuid().ToString("N");using(var input=Assembly.GetExecutingAssembly().GetManifestResourceStream("FreecamNative"))using(var output=File.Create(temporary))input.CopyTo(output);if(File.Exists(target))File.Replace(temporary,target,target+".backup",true);else File.Move(temporary,target);label.Text="Модуль установлен. Запустите OBS.\nОткройте Freecam Native Setup.exe, подключите OBS,\nвыберите готовую сцену и камеру.\nПанель расходов также доступна в Сервис / Tools → Freecam.";button.Enabled=false;}}catch(UnauthorizedAccessException){MessageBox.Show("Папка OBS защищена. Запустите установщик от имени администратора.","Freecam");}catch(Exception error){MessageBox.Show(error.Message,"Freecam");}};Application.Run(form);}
}
